const _teenthDate = function teenthDate(){
  return function(year, month, dayNum){
    const base = new Date(year, month, 13);
    const diff = (dayNum - base.getDay() + 7) % 7;
    return new Date(year, month, 13 + diff);
  };
};

const _nthDate = function nthDate(){
  return function(year, month, n, dayNum){
    const first = new Date(year, month, 1);
    const diff = (dayNum - first.getDay() + 7) % 7;
    const day = 1 + diff + (n - 1) * 7;
    return new Date(year, month, day);
  };
};

