// OCR Numbers — convert pipe/underscore digit grids to strings
const _digits = function digits(){
  // Each digit is a 4-row × 3-column grid. Row 3 is always blank.
  // Stored as array of 3 strings (rows 0-2); row 3 ignored.
  return {
    " _ \n| |\n|_|": "0",
    "   \n  |\n  |": "1",
    " _ \n _|\n|_ ": "2",
    " _ \n _|\n _|": "3",
    "   \n|_|\n  |": "4",
    " _ \n|_ \n _|": "5",
    " _ \n|_ \n|_|": "6",
    " _ \n  |\n  |": "7",
    " _ \n|_|\n|_|": "8",
    " _ \n|_|\n _|": "9"
  };
};

const _convert = function convert(digits){
  return function(input) {
    // Split input into lines
    const lines = input.split("\n");

    // Validate: total lines must be a multiple of 4
    if (lines.length % 4 !== 0) {
      throw new Error("Number of input lines is not a multiple of four");
    }

    const results = [];

    // Process each group of 4 lines
    for (let g = 0; g < lines.length; g += 4) {
      const group = lines.slice(g, g + 4);
      const row0 = group[0];
      const row1 = group[1];
      const row2 = group[2];
      // row3 = group[3] is always blank

      // Determine how many digits (each is 3 columns wide)
      const width = row0.length;

      // All rows must have the same length
      if (row1.length !== width || row2.length !== width) {
        throw new Error("Each line within a group must have the same width");
      }

      // Width must be a multiple of 3
      if (width % 3 !== 0) {
        throw new Error("Number of input columns is not a multiple of three");
      }

      const numDigits = width / 3;
      let result = "";

      for (let d = 0; d < numDigits; d++) {
        const col = d * 3;
        const chunk = row0.slice(col, col + 3) + "\n"
                    + row1.slice(col, col + 3) + "\n"
                    + row2.slice(col, col + 3);
        const digit = digits[chunk];
        result += digit !== undefined ? digit : "?";
      }

      results.push(result);
    }

    return results.join(",");
  };
};

