class Palindromes {
  static generate({ minFactor, maxFactor }) {
    if (minFactor > maxFactor) throw new Error("min must be <= max");

    const isPalindrome = (n) => {
      const s = String(n);
      return s === s.split("").reverse().join("");
    };

    let smallest = null;
    let largest = null;

    for (let i = minFactor; i <= maxFactor; i++) {
      for (let j = i; j <= maxFactor; j++) {
        const product = i * j;
        if (!isPalindrome(product)) continue;
        if (smallest === null || product < smallest.value) {
          smallest = { value: product, factors: [[i, j]] };
        } else if (product === smallest.value) {
          smallest.factors.push([i, j]);
        }
        if (largest === null || product > largest.value) {
          largest = { value: product, factors: [[i, j]] };
        } else if (product === largest.value) {
          largest.factors.push([i, j]);
        }
      }
    }

    return {
      smallest: smallest || { value: null, factors: [] },
      largest: largest || { value: null, factors: [] }
    };
  }
}
)};
