const _translateWord = function translateWord(){return( word => {
  const vowels = /[aeiou]/;
  // Rule 1: starts with vowel, or "xr", or "yt"
  if (vowels.test(word[0]) || word.startsWith("xr") || word.startsWith("yt")) {
    return word + "ay";
  }
  // Rule 3: consonants (possibly zero) followed by "qu"
  const quMatch = word.match(/^([^aeiou]*)(qu)/);
  if (quMatch) {
    return word.slice(quMatch[0].length) + quMatch[0] + "ay";
  }
  // Rule 4: consonants followed by "y"
  const yMatch = word.match(/^([^aeiou]+)(y)/);
  if (yMatch) {
    return word.slice(yMatch[1].length) + yMatch[1] + "ay";
  }
  // Rule 2: one or more consonants at start
  const consMatch = word.match(/^([^aeiou]+)/);
  if (consMatch) {
    return word.slice(consMatch[1].length) + consMatch[1] + "ay";
  }
  return word + "ay";
})};

