    }
    if (counts[0].count === 3) {
      const kickers = counts.filter(c => c.count === 1).map(c => c.rank).sort((a, b) => b - a);
      return { type: 3, tiebreak: [counts[0].rank, ...kickers] };
    }
    if (counts[0].count === 2 && counts[1].count === 2) {
      const pairRanks = counts.filter(c => c.count === 2).map(c => c.rank).sort((a, b) => b - a);
      const kicker = counts.find(c => c.count === 1).rank;
